--- <campaign>/ios-harness-before-projection.swift	2026-10-18 18:40:38
+++ <campaign>/apple-sdk/Sources/XrayAppleClient/Debug/XrayProtocolDeviceProbe.swift	2026-10-18 18:40:38
@@ -125,7 +125,7 @@
                     providerBundleIdentifier: XrayClientProfile.defaultProviderBundleIdentifier(
                         hostBundleIdentifier: Bundle.main.bundleIdentifier),
                     serverAddress: item.serverAddress, configJSON: item.configJSON,
-                    debugLoggingEnabled: false, useTunFileDescriptor: true, tunRuntimeProfile: .mobile)
+                    debugLoggingEnabled: false, useTunFileDescriptor: ProcessInfo.processInfo.environment["XRAY_PROJECTION_PACKET_PUMP"] != "1", tunRuntimeProfile: .mobile)
                 if fixture.mode == .udpSweep {
                     try await udpSweep(fixture, profile: profile, update: update)
                     try await cleanup()
@@ -505,6 +505,14 @@
     }

     private func sample(cycle: Int, stage: String) async throws {
+        if ProcessInfo.processInfo.environment["XRAY_ADAPTER_PROJECTION_DEVICE_CHECK"] == "1" {
+            guard let counts = try await controller.protocolProbeCPU(),
+                  let tcp = counts["admissionTCP"], let udp = counts["admissionUDP"], tcp > 0, udp > 0,
+                  counts["invalidTuples"] == 0 else { throw Failure.configuration }
+            emit(["event": "host-adapter-projection", "result": "passed", "tcpCallbacks": tcp,
+                  "udpCallbacks": udp, "stage": stage,
+                  "backend": ProcessInfo.processInfo.environment["XRAY_PROJECTION_PACKET_PUMP"] == "1" ? "packet-pump" : "file-descriptor"])
+        }
         if let events = try await controller.protocolProbeNetworkEvents() {
             emit(["event": "network-observer", "stage": stage, "events": events])
         }
